SELECT DATE_FORMAT(stores.opened_date, 'yyyy-MM') AS opened_month, ROUND(AVG(orders.shipping_fee), 2) AS avg_shipping_fee, AVG(orders.amount) AS avg_amount FROM orders RIGHT OUTER JOIN stores ON orders.store_id = stores.id LEFT OUTER JOIN customers ON orders.customer_id = customers.id WHERE stores.sqft >= 12638 GROUP BY DATE_FORMAT(stores.opened_date, 'yyyy-MM') ORDER BY opened_month LIMIT 5
